167	        </Text>
168	      )}
169	
170	      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
171	        <Box>
172	          {/* Deviation from the base file (same labelled-comment convention as
173	                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
