244	                value={variant.priceAdjustments.reduce((acc: number, adj: SfccVariant) => acc + (adj.price ?? 0), 0)}
245	              />
246	            </Text>
247	          </Text>
248	          <PromoPopover ml={2}>
249	            <Stack>
250	              {promos?.map((promo: SfccVariant) => (
251	                <Text key={promo?.id} fontSize="sm">
252	                  {promo?.calloutMsg}
253	                </Text>
254	              ))}
255	            </Stack>
256	          </PromoPopover>
257	        </Flex>
258	      )}
259	    </Stack>
260	  );
261	};
262	
263	export default ItemAttributes;
